import logging

from ta_messaging.message_parser import MessageParser
from ta_pdml_parser.uesim_pdml_parser import UesimPdmlParser
from ute_common_abstract_core.network_elem_identification import CellIdentification
from ute_common_abstract_core.message import Message
import re


class RtgMessageParser(MessageParser):
    """Parser for messages of RTG Ue simulator"""

    def __init__(self):
        """Create instance of UesimPdmlParser"""
        self.parser = UesimPdmlParser()
        self.protocol = "rrc"  # TODO: replace hardcode with method returning data protocol

    def parse(self, unparsed_message):
        """
        Parses given partially-parsed message into Message instance

        :param unparsed_message: message to be fully parsed
        :return: instance of Message (derived from dict)
        """
        protocol = unparsed_message.protocol
        pdu_type = unparsed_message.meta_data["pdu_type"]
        msg_payload = unparsed_message.msg_payload

        if isinstance(unparsed_message.owner, CellIdentification) and pdu_type == "???":  # TODO: to be removed
            match = re.search(                                               # not needed from CUS_1.0.REL.240207.04
                r"(?P<message_type>SystemInformationBlockType\d{1,2})-BR-r13", unparsed_message.message_type
            )  # MIB/SIBs
            message_type = match.group("message_type") if match else unparsed_message.message_type
        else:
            message_type = pdu_type  # PCCH/MCCH

        string_to_parse = "@dump {} {} {}".format(protocol, message_type, msg_payload)

        asn_value_msg = self.parser._convert_uesim_hex_msg2asn_value(string_to_parse)
        payload_as_dict = self.parser._convert_asn_value2pythons_structure(asn_value_msg)

        fully_parsed_msg = Message(payload_as_dict, unparsed_message.meta_data)
        return fully_parsed_msg

    #  -- not useful methods until we read UESIM console output

    @staticmethod
    def _get_pdu_type_from_payload(payload):
        # example payload: >> CCCH:rrcConnectionRequest 500000000026
        direction_mapping = {">>": "ul", "<<": "dl"}
        direction = payload.split()[0]
        if direction not in direction_mapping:
            messaging_logger = logging.getLogger("messaging")
            messaging_logger.error("Parser: {} direction unrecognized".format(direction))
            return None
        pdu_direction = direction_mapping[direction]
        pdu_rest = payload.split(":")[0].split()[-1]  # pdu_rest = 'CCCH'
        pdu_rest = pdu_rest.lower()  # pdu_rest = 'ccch'
        return "{}-{}".format(pdu_direction, pdu_rest)  # ul-ccch

    @staticmethod
    def _get_msg_hex_from_payload(payload):
        # example payload: >> CCCH:rrcConnectionRequest 500000000026
        msg_hex = payload.split()[-1]
        return msg_hex
